// Pins what add() in app/app.js makes, so a backup the app itself made always imports again (Khoa's review of commit B:
// isValidTodo rejects whitespace-only titles and non-string ids). app.js is a plain page script with no exports, so it
// runs unchanged in a vm context with a minimal fake page. Run: node --test
// Due dates (plan/2026-10-19-han-chot-cho-viec.md, PR A): the clock is fixed at 06:00 on 10/11/2026 in UTC+7 (23:00 on
// 09/11 in UTC), and timers are fake, so the 10-second Undo runs on demand.
process.env.TZ = 'Asia/Ho_Chi_Minh';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');
const due = require('../app/due.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');
const NOW = Date.UTC(2026, 10, 9, 23, 0); // 06:00 on 10/11/2026 in UTC+7

// A fake element. A list remembers the rows appended to it (cleared by innerHTML = ''); focus() moves the fake
// document's focus and fires onfocus, like a browser.
function fakeElement(doc) {
  let html = '';
  const el = {
    textContent: '', hidden: false, value: '', className: '', dataset: {}, attributes: {}, rows: [],
    get innerHTML() { return html; },
    set innerHTML(v) { html = v; if (v === '') el.rows = []; },
    append(child) { el.rows.push(child); },
    querySelector(sel) { return (el.children[sel] ||= fakeElement(doc)); },
    children: {},
    setAttribute(name, v) { el.attributes[name] = String(v); },
    getAttribute(name) { return name in el.attributes ? el.attributes[name] : null; },
    focus() { if (doc) { doc.activeElement = el; if (el.onfocus) el.onfocus({}); } },
  };
  return el;
}

// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
// saveResult: what store.save returns ('saved', 'failed' or 'skipped').
function loadApp(initial = [], { saveResult = 'saved' } = {}) {
  const elements = {};
  const saved = [];
  const replaced = [];
  const store = {
    readError: false,
    load() { return { todos: initial, readError: false }; },
    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return saveResult; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const document = {
    activeElement: null,
    querySelector(sel) { return (elements[sel] ||= fakeElement(document)); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(document); },
  };
  document.body = fakeElement(document);
  document.activeElement = document.body;
  // index.html ships the Undo button hidden.
  document.querySelector('#undo').hidden = true;
  const timers = new Map();
  let nextTimer = 1;
  const setTimeout = (fn, ms) => { timers.set(nextTimer, { fn, ms }); return nextTimer++; };
  const clearTimeout = (id) => { timers.delete(id); };
  // Runs every pending timer due within `ms`.
  const runTimers = (ms) => {
    for (const [id, t] of [...timers]) if (t.ms <= ms && timers.delete(id)) t.fn();
  };
  class FixedDate extends Date {
    constructor(...args) { if (args.length) super(...args); else super(NOW); }
    static now() { return NOW; }
  }
  vm.runInNewContext(appJs, { ...backup, ...due, store, document, crypto, Date: FixedDate, setTimeout, clearTimeout });
  const $ = (sel) => document.querySelector(sel);
  const submit = (value, dueDate = '') => {
    $('#title').value = value;
    $('#due').value = dueDate;
    $('#add').onsubmit({ preventDefault() {} });
  };
  // The confirm dialog records each question and answers "Huỷ".
  const asked = [];
  Object.assign(document.querySelector('#confirm'), {
    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
    addEventListener(type, fn) { queueMicrotask(fn); },
  });
  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
  const count = () => document.querySelector('#count').textContent;
  // Clicks a filter tab: 'all', 'open' or 'done'.
  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
  const emptyShown = () => !document.querySelector('#empty').hidden;

  // Rows on screen, in screen order.
  const rows = () => $('#list').rows;
  const titleOf = (li) => li.querySelector('.title').textContent;
  const titles = () => rows().map(titleOf);
  const row = (title) => {
    const li = rows().find((r) => titleOf(r) === title);
    assert.ok(li, `row "${title}" on screen`);
    return li;
  };
  const dueText = (title) => row(title).querySelector('.due').textContent;
  const overdueText = (title) => row(title).querySelector('.overdue-tag').textContent;
  const isOverdueRow = (title) => row(title).className.split(' ').includes('overdue');
  const sortBy = (v) => { $('#sort').value = v; $('#sort').onchange({ target: $('#sort') }); };
  const message = () => $('#message').textContent;
  const undoShown = () => !$('#undo').hidden;
  const clickUndo = () => $('#undo').onclick({});
  // A row's date field: focus it, fire change with a value (as the picker or each typed part does), leave it.
  const focusDate = (title) => { const el = row(title).querySelector('.due-input'); el.focus(); return el; };
  const changeDate = (el, v) => { el.value = v; el.onchange({ target: el }); };
  // While blur runs the browser has no focused element yet; relatedTarget is where focus goes next.
  const blurDate = (el, relatedTarget = null) => {
    document.activeElement = document.body;
    el.onblur({ target: el, relatedTarget });
    if (relatedTarget && document.activeElement === document.body) relatedTarget.focus();
  };
  const toggleRow = (title) => row(title).querySelector('.toggle').onchange({});
  const removeRow = (title) => row(title).querySelector('.remove').onclick({});
  const lastSaved = () => saved.at(-1);
  const savedTodo = (title) => lastSaved().find((t) => t.title === title);
  return {
    submit, saved, replaced, asked, pick, count, filterBy, emptyShown, document, $, rows, titles, row, dueText, overdueText,
    isOverdueRow, sortBy, message, undoShown, clickUndo, focusDate, changeDate, blurDate, toggleRow, removeRow, lastSaved,
    savedTodo, runTimers,
  };
}

// A file whose text() resolves only when the test says so.
function slowFile(text) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
}

function backupOf(...titles) {
  return backup.toBackupText(titles.map((title, i) => ({ id: `id-${title}-${i}`, title, done: false, createdAt: 1 })));
}

test('add form: trims the title and makes a string id', () => {
  const { submit, saved } = loadApp();
  submit('  Mua sữa  ');
  assert.equal(saved.length, 1);
  const [t] = saved[0];
  assert.equal(t.title, 'Mua sữa');
  assert.equal(typeof t.id, 'string');
  assert.notEqual(t.id, '');
  assert.equal(t.done, false);
  assert.equal(typeof t.createdAt, 'number');
});

test('add form: skips a whitespace-only title', () => {
  const { submit, saved } = loadApp();
  submit('   ');
  submit('\t\n');
  assert.equal(saved.length, 0);
});

test('open-todo count line: a dot every three digits from 1,000 up, like every other sentence (Linh, R9)', () => {
  const todos = (n, done = false) =>
    Array.from({ length: n }, (_, i) => ({ id: `id-${done}-${i}`, title: `Việc ${i}`, done, createdAt: 1 }));
  const { submit, count } = loadApp([...todos(999), ...todos(5, true)]);
  assert.equal(count(), '999 việc chưa xong');
  submit('Việc thứ 1000');
  assert.equal(count(), '1.000 việc chưa xong');
  assert.equal(loadApp(todos(12)).count(), '12 việc chưa xong');
  assert.equal(loadApp(todos(2001)).count(), '2.001 việc chưa xong');
  assert.equal(loadApp(todos(12500)).count(), '12.500 việc chưa xong');
});

test('open-todo count line counts the whole list, whatever the filter (T-013)', () => {
  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
  const { count, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, true), todo(5, true)]);
