// A todo has: id, title, done, createdAt, and maybe dueDate ('YYYY-MM-DD'; no key when it has none). No tags, no owner.
// Saving and importing decisions live in backup.js (persist, importBackup), date logic in due.js; this file only wires
// them to the page.
let todos = store.load().todos;
let filter = 'all';
let sort = 'added'; // 'added' | 'due'. Not remembered: a reload shows added order again (A11).
let undo = null; // { restore, timer } while "Hoàn tác" is offered. Page memory only, never saved.
let changedInPlace = false; // a row's date was saved and drawn in place; the list redraws when that field is left (Q3)
let rendering = false;

const $ = (sel) => document.querySelector(sel);

// Fills {title} as plain text: a function replacer, so "$&" or "$1" in a title stay as typed.
const withTitle = (template, title) => template.replace('{title}', () => title);

function add(title, dueDate) {
  const t = { id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() };
  if (isValidDueDate(dueDate)) t.dueDate = dueDate; // an empty field adds no key (AC2); a past date is fine (A4)
  todos.push(t);
  commit();
}

function toggle(id) {
  const t = todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
  commit();
}

function remove(id) {
  todos = todos.filter((x) => x.id !== id);
  commit();
}

// On a row's date `change`. Only a valid, different date is saved. An empty value (a part being retyped with the
// keyboard) does nothing here, so it never drops a saved date; leaving the field decides (Q3). Returns the todo if saved.
function setDue(id, value) {
  const t = todos.find((x) => x.id === id);
  if (!t || !isValidDueDate(value) || t.dueDate === value) return null;
  t.dueDate = value;
  save();
  changedInPlace = true;
  return t;
}

// On leaving a row's date field while it is empty. `before`: the field's value when it got focus. Returns true if saved.
function clearDue(id, before) {
  const t = todos.find((x) => x.id === id);
  if (!t || !isValidDueDate(t.dueDate)) return false; // nothing shown to clear; a broken value stays as it is (A14)
  const old = t.dueDate; // the date saved now, which may be one set during this same focus
  delete t.dueDate;
  const notSaved = persist(store, todos).message;
  // Set and cleared within this focus: the customer loses no date they had before, so no D5 and no Undo (Q3).
  if (before === '') {
    show(notSaved);
    return true;
  }
  offerUndo(notSaved || withTitle(DUE_TEXT.cleared, t.title), () => {
    const again = todos.find((x) => x.id === id);
    if (again) again.dueDate = old;
  });
  return true;
}

function commit() {
  save();
  render();
}

function save() {
  show(persist(store, todos).message);
}

// Every new message removes the Undo button, so add, toggle, delete, a date change and import all end it (A16);
// filter, sort and leaving a date field show nothing, so it stays.
function show(message) {
  clearUndo();
  $('#message').textContent = message || '';
}

// One Undo for the whole app (plan Q7): restore() puts the data back; saving and redrawing are done here.
function offerUndo(message, restore) {
  show(message);
  $('#undo').hidden = false;
  undo = { restore, timer: setTimeout(clearUndo, 10000) };
}

function clearUndo() {
  if (undo) clearTimeout(undo.timer);
  undo = null;
  $('#undo').hidden = true;
}

function visible() {
  let shown = todos;
  if (filter === 'open') shown = todos.filter((t) => !t.done);
  if (filter === 'done') shown = todos.filter((t) => t.done);
  return sort === 'due' ? sortByDue(shown) : shown; // a new array: the saved order never changes (Q6)
}

// The parts of a row that change with its date and done state. Called on each draw and after a date change in place.
function showDue(li, t, today) {
  const overdue = isOverdue(t, today);
  li.className = [t.done ? 'done' : '', overdue ? 'overdue' : ''].filter(Boolean).join(' ');
  li.querySelector('.due').textContent = isValidDueDate(t.dueDate) ? formatDueDate(t.dueDate) : '';
  li.querySelector('.overdue-tag').textContent = overdue ? DUE_TEXT.overdue : '';
}

function row(t, today) {
  const li = document.createElement('li');
  li.dataset.id = t.id;
  // A fixed template with no user text; the title, label and dates go in below as text or attributes (S3).
  li.innerHTML =
    `<label><input type="checkbox" class="toggle" ${t.done ? 'checked' : ''}> <span class="title"></span></label>` +
    '<span class="due-box"><input type="date" class="due-input"><span class="due"></span><span class="overdue-tag"></span></span>' +
    '<button class="remove" aria-label="Xoá">×</button>';
  li.querySelector('.title').textContent = t.title;
  const box = li.querySelector('.toggle');
  const date = li.querySelector('.due-input');
  const del = li.querySelector('.remove');
  // So render() can put focus back on the same control of the same todo.
  for (const [el, part] of [[box, 'toggle'], [date, 'due-input'], [del, 'remove']]) {
    el.dataset.id = t.id;
    el.dataset.part = part;
  }
  box.onchange = () => toggle(t.id);
  del.onclick = () => remove(t.id);
  date.value = isValidDueDate(t.dueDate) ? t.dueDate : '';
  date.setAttribute('aria-label', withTitle(DUE_TEXT.rowLabel, t.title));
  date.onfocus = () => { date.dataset.before = date.value; };
  date.onchange = () => {
    const changed = setDue(t.id, date.value);
    if (changed) showDue(li, changed, localDateString(new Date()));
  };
  date.onblur = (e) => {
    if (rendering) return; // a browser may blur a field while render() removes it
    if (date.value === '' && clearDue(t.id, date.dataset.before)) changedInPlace = true;
    if (changedInPlace) render(e.relatedTarget);
  };
  showDue(li, t, today);
  return li;
}

// focusTarget: where focus is going, when called from a blur (the browser has not moved focus yet at that point).
function render(focusTarget) {
  const list = $('#list');
  const from = focusTarget || document.activeElement;
  const keep = from && from.dataset && from.dataset.part ? { id: from.dataset.id, part: from.dataset.part } : null;
  const today = localDateString(new Date()); // again on every draw (F3 step 5)
  let refocus = null;
  rendering = true;
  list.innerHTML = '';
  for (const t of visible()) {
    const li = row(t, today);
    if (keep && keep.id === t.id) refocus = li.querySelector(`.${keep.part}`);
    list.append(li);
  }
  rendering = false;
  changedInPlace = false;
  const open = todos.filter((t) => !t.done).length;
  // Every todo done (and the list not empty): say so instead of "0 việc chưa xong" (Thảo, PR 3).
  $('#count').textContent = open === 0 && todos.length > 0 ? 'Đã xong hết' : `${formatCount(open)} việc chưa xong`;
  $('#unreadable').hidden = !store.readError;
  // Based on the whole list, not the filter; and not shown on a read error, where the list only looks empty.
  $('#empty').hidden = todos.length > 0 || store.readError;
  if (refocus) refocus.focus();
}

// Resolves true only when the customer picks "Thay"; Esc and "Huỷ" resolve false.
function ask(question) {
  const dialog = $('#confirm');
  $('#confirm-text').textContent = question;
  dialog.returnValue = '';
  dialog.showModal();
  return new Promise((resolve) => {
    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'yes'), { once: true });
  });
}

$('#add').onsubmit = (e) => {
  e.preventDefault();
  const input = $('#title');
  const date = $('#due');
  if (input.value.trim()) add(input.value, date.value);
  input.value = '';
  date.value = '';
};

$('#filters').onclick = (e) => {
  const f = e.target.dataset.filter;
  if (!f) return;
  filter = f;
  document.querySelectorAll('#filters button').forEach((b) => b.classList.toggle('on', b.dataset.filter === f));
  render();
};

$('#sort').value = sort; // a browser may restore the last choice on reload; the list starts in added order (A11)
$('#sort').onchange = () => {
  sort = $('#sort').value === 'due' ? 'due' : 'added';
  render();
};

$('#undo').onclick = () => {
  if (!undo) return;
  undo.restore();
  const notSaved = persist(store, todos).message;
  render();
  show(notSaved || DUE_TEXT.undone); // show() also removes the button
};

$('#export').onclick = () => {
  if (todos.length === 0) return show(MESSAGES.nothingToBackUp);
  const text = toBackupText(todos);
  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = backupFileName(new Date());
  document.body.append(a);
  a.click();
  a.remove();
  // Revoking right after click() can break the download on Safari iOS, so wait.
  setTimeout(() => URL.revokeObjectURL(url), 10000);
  show(tooBigToImport(text) ? MESSAGES.backupTooBig : fill(MESSAGES.backedUp, { n: todos.length }));
};

$('#import').onchange = async (e) => {
  const input = e.target;
  const file = input.files[0];
  input.value = ''; // so the same file can be picked again
  if (!file) return;
  show(MESSAGES.reading);
  // Counted when importBackup decides whether to ask (after the file is read), not now: another import, an add or a
  // delete may change the list while the file is being read. importBackup only reads current.length and returns
  // current itself when nothing was replaced.
  const current = { get length() { return todos.length; } };
  const result = await importBackup({ store, current, file, ask });
  if (result.todos !== current) todos = result.todos;
  show(result.message);
  render();
};

$('#unreadable').textContent = MESSAGES.unreadable;
$('#empty').textContent = MESSAGES.emptyList;
render();

