1	// Due dates: checking, today's date, overdue, display and sorting. No DOM and no browser storage here, so it can be tested
2	// in Node. A due date is a calendar day 'YYYY-MM-DD' (not a moment in time); a todo without one has no dueDate key.
3	// Never build a Date from a dueDate string (it is read as UTC) and never take the day from a UTC ISO string: both shift
4	// the day at UTC+7.
5	
6	// New screen text (plan D1-D6, D8, D9). {title} is the todo's own title; fill it with a function replacer, as text only.
7	const DUE_TEXT = {
8	  label: 'Hạn chót',
9	  rowLabel: 'Hạn chót của việc {title}',
10	  due: 'Hạn {date}',
11	  overdue: 'Quá hạn',
12	  cleared: 'Đã bỏ hạn chót của việc {title}.',
13	  undo: 'Hoàn tác',
14	  sortBy: 'Xếp theo',
15	  sortAdded: 'Thứ tự thêm',
16	  sortDue: 'Hạn chót',
17	  undone: 'Đã hoàn tác.',
18	};
19	
20	// A string in the fixed form YYYY-MM-DD that is a real day (no 2026-02-30). Date.UTC and getUTC* do not depend on the time zone.
21	function isValidDueDate(v) {
22	  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
23	  const [y, m, d] = v.split('-').map(Number);
24	  const date = new Date(Date.UTC(y, m - 1, d));
25	  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
26	}
27	
28	// The customer's own day on this machine (local time), as YYYY-MM-DD.
29	function localDateString(date) {
30	  const pad = (n) => String(n).padStart(2, '0');
31	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
32	}
33	
34	// Open and due before today. Due today is not overdue; a done todo never is. The fixed 4-2-2 form compares as strings.
35	function isOverdue(todo, today) {
36	  return !todo.done && isValidDueDate(todo.dueDate) && todo.dueDate < today;
37	}
38	
39	// 'Hạn DD/MM/YYYY'. Only for valid values.
40	function formatDueDate(s) {
41	  const [y, m, d] = s.split('-');
42	  return DUE_TEXT.due.replace('{date}', `${d}/${m}/${y}`);
43	}
44	
45	// A new array (the stored order is never changed): valid dates ascending, then todos with no or a broken dueDate.
46	// Ties keep the given order, by comparing the original index rather than relying on a stable sort.
47	function sortByDue(todos) {
48	  return todos
49	    .map((todo, index) => ({ todo, index, key: isValidDueDate(todo.dueDate) ? todo.dueDate : null }))
50	    .sort((a, b) => {
51	      if (a.key !== b.key) {
52	        if (a.key === null) return 1;
53	        if (b.key === null) return -1;
54	        return a.key < b.key ? -1 : 1;
55	      }
56	      return a.index - b.index;
57	    })
58	    .map((x) => x.todo);
59	}
60	
61	if (typeof module !== 'undefined') {
62	  module.exports = { DUE_TEXT, isValidDueDate, localDateString, isOverdue, formatDueDate, sortByDue };
63	}
