3	// runs unchanged in a vm context with a minimal fake page. Run: node --test
4	// Due dates (plan/2026-10-19-han-chot-cho-viec.md, PR A): the clock is fixed at 06:00 on 10/11/2026 in UTC+7 (23:00 on
5	// 09/11 in UTC), and timers are fake, so the 10-second Undo runs on demand.
6	process.env.TZ = 'Asia/Ho_Chi_Minh';
7	const test = require('node:test');
8	const assert = require('node:assert/strict');
9	const fs = require('node:fs');
10	const path = require('node:path');
