19	// A fake element. A list remembers the rows appended to it (cleared by innerHTML = ''); focus() moves the fake
20	// document's focus and fires onfocus, like a browser.
21	function fakeElement(doc) {
22	  let html = '';
23	  const el = {
24	    textContent: '', hidden: false, value: '', className: '', dataset: {}, attributes: {}, rows: [],
25	    get innerHTML() { return html; },
26	    set innerHTML(v) { html = v; if (v === '') el.rows = []; },
27	    append(child) { el.rows.push(child); },
28	    querySelector(sel) { return (el.children[sel] ||= fakeElement(doc)); },
29	    children: {},
30	    setAttribute(name, v) { el.attributes[name] = String(v); },
31	    getAttribute(name) { return name in el.attributes ? el.attributes[name] : null; },
32	    focus() { if (doc) { doc.activeElement = el; if (el.onfocus) el.onfocus({}); } },
33	  };
34	  return el;
35	}
