37	// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
38	// saveResult: what store.save returns ('saved', 'failed' or 'skipped').
39	function loadApp(initial = [], { saveResult = 'saved' } = {}) {
40	  const elements = {};
41	  const saved = [];
42	  const replaced = [];
43	  const store = {
44	    readError: false,
45	    load() { return { todos: initial, readError: false }; },
46	    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return saveResult; },
47	    replace(todos) { replaced.push(todos); return 'saved'; },
48	  };
49	  const document = {
50	    activeElement: null,
51	    querySelector(sel) { return (elements[sel] ||= fakeElement(document)); },
52	    querySelectorAll() { return []; },
53	    createElement() { return fakeElement(document); },
54	  };
55	  document.body = fakeElement(document);
56	  document.activeElement = document.body;
57	  // index.html ships the Undo button hidden.
58	  document.querySelector('#undo').hidden = true;
59	  const timers = new Map();
60	  let nextTimer = 1;
61	  const setTimeout = (fn, ms) => { timers.set(nextTimer, { fn, ms }); return nextTimer++; };
62	  const clearTimeout = (id) => { timers.delete(id); };
63	  // Runs every pending timer due within `ms`.
64	  const runTimers = (ms) => {
65	    for (const [id, t] of [...timers]) if (t.ms <= ms && timers.delete(id)) t.fn();
66	  };
67	  class FixedDate extends Date {
68	    constructor(...args) { if (args.length) super(...args); else super(NOW); }
69	    static now() { return NOW; }
70	  }
71	  vm.runInNewContext(appJs, { ...backup, ...due, store, document, crypto, Date: FixedDate, setTimeout, clearTimeout });
72	  const $ = (sel) => document.querySelector(sel);
73	  const submit = (value, dueDate = '') => {
74	    $('#title').value = value;
75	    $('#due').value = dueDate;
76	    $('#add').onsubmit({ preventDefault() {} });
77	  };
78	  // The confirm dialog records each question and answers "Huỷ".
79	  const asked = [];
80	  Object.assign(document.querySelector('#confirm'), {
81	    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
82	    addEventListener(type, fn) { queueMicrotask(fn); },
83	  });
84	  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
85	  const count = () => document.querySelector('#count').textContent;
86	  // Clicks a filter tab: 'all', 'open' or 'done'.
87	  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
88	  const emptyShown = () => !document.querySelector('#empty').hidden;
89	
90	  // Rows on screen, in screen order.
91	  const rows = () => $('#list').rows;
92	  const titleOf = (li) => li.querySelector('.title').textContent;
93	  const titles = () => rows().map(titleOf);
94	  const row = (title) => {
95	    const li = rows().find((r) => titleOf(r) === title);
96	    assert.ok(li, `row "${title}" on screen`);
97	    return li;
98	  };
99	  const dueText = (title) => row(title).querySelector('.due').textContent;
100	  const overdueText = (title) => row(title).querySelector('.overdue-tag').textContent;
101	  const isOverdueRow = (title) => row(title).className.split(' ').includes('overdue');
102	  const sortBy = (v) => { $('#sort').value = v; $('#sort').onchange({ target: $('#sort') }); };
103	  const message = () => $('#message').textContent;
104	  const undoShown = () => !$('#undo').hidden;
105	  const clickUndo = () => $('#undo').onclick({});
106	  // A row's date field: focus it, fire change with a value (as the picker or each typed part does), leave it.
107	  const focusDate = (title) => { const el = row(title).querySelector('.due-input'); el.focus(); return el; };
108	  const changeDate = (el, v) => { el.value = v; el.onchange({ target: el }); };
109	  // While blur runs the browser has no focused element yet; relatedTarget is where focus goes next.
110	  const blurDate = (el, relatedTarget = null) => {
111	    document.activeElement = document.body;
112	    el.onblur({ target: el, relatedTarget });
113	    if (relatedTarget && document.activeElement === document.body) relatedTarget.focus();
114	  };
115	  const toggleRow = (title) => row(title).querySelector('.toggle').onchange({});
116	  const removeRow = (title) => row(title).querySelector('.remove').onclick({});
117	  const lastSaved = () => saved.at(-1);
118	  const savedTodo = (title) => lastSaved().find((t) => t.title === title);
119	  return {
120	    submit, saved, replaced, asked, pick, count, filterBy, emptyShown, document, $, rows, titles, row, dueText, overdueText,
121	    isOverdueRow, sortBy, message, undoShown, clickUndo, focusDate, changeDate, blurDate, toggleRow, removeRow, lastSaved,
122	    savedTodo, runTimers,
123	  };
124	}
