test('F2: change saves at once with no Undo; clearing on leave has D5 and Undo; Undo restores; 10 s hides it (AC6, Q5)', () => {
  const app = loadApp([todo('B', { dueDate: '2026-11-15' })]);
  let input = app.focusDate('B');
  app.changeDate(input, '2026-11-11');
