  assert.equal(app.dueText('B'), '');
  assert.equal(app.message(), D5('B'));
  assert.equal(app.undoShown(), true);

  app.clickUndo();
  assert.equal(app.savedTodo('B').dueDate, '2026-11-11');
  assert.equal(app.dueText('B'), 'Hạn 11/11/2026');
  assert.equal(app.message(), D9);
  assert.equal(app.undoShown(), false);

  input = app.focusDate('B');
  app.changeDate(input, '');
  app.blurDate(input);
  assert.equal(app.undoShown(), true);
  app.runTimers(9999);
  assert.equal(app.undoShown(), true, 'still there before 10 s');
  app.runTimers(10000);
  assert.equal(app.undoShown(), false, 'gone after 10 s');
  assert.equal('dueDate' in app.savedTodo('B'), false);
});

