test('A16: Undo goes on add, toggle, delete, another date change and import; stays on filter, sort and leaving a date field', async () => {
  const clearB = (app) => {
    const input = app.focusDate('B');
    app.changeDate(input, '');
    app.blurDate(input);
    assert.equal(app.undoShown(), true);
  };
  const start = () => loadApp([todo('A', { dueDate: '2026-11-20' }), todo('B', { dueDate: '2026-11-12' }), todo('C')]);

  let app = start();
  clearB(app);
  app.filterBy('open');
  assert.equal(app.undoShown(), true, 'filter');
  app.sortBy('due');
  assert.equal(app.undoShown(), true, 'sort');
  const a = app.focusDate('A');
  app.blurDate(a);
  assert.equal(app.undoShown(), true, 'leaving a date field without clearing it');
  app.submit('Mới');
  assert.equal(app.undoShown(), false, 'add');

  app = start(); clearB(app); app.toggleRow('C');
  assert.equal(app.undoShown(), false, 'toggle');
  app = start(); clearB(app); app.removeRow('C');
  assert.equal(app.undoShown(), false, 'delete');
  app = start(); clearB(app);
  const c = app.focusDate('C');
  app.changeDate(c, '2026-11-30');
  assert.equal(app.undoShown(), false, 'another date change');
  app = start(); clearB(app);
  await app.pick({ size: 10, text: async () => backupOf('X') });
  assert.equal(app.undoShown(), false, 'import');
});

